(function(){
'use strict';
const C={
zh:{title:'稍等一下，專屬於你的可愛模樣即將登場',label:'AI 專屬角色製作進度',note:'圖片完成後將自動進入選擇畫面',steps:['上傳','排隊','生成','完成'],uploading:'正在上傳照片…',queued:'照片已收到，正在準備生成…',generating:'AI 正在製作您的專屬角色…',ready:'完成！準備看看您的專屬角色',failed:'生成未完成，請通知工作人員'},
jp:{title:'もうすぐ、かわいいあなたに会えます！',label:'AIキャラクター作成進捗',note:'完成後、自動的に選択画面へ移動します',steps:['送信','準備','生成','完成'],uploading:'写真を送信しています…',queued:'写真を受信しました。準備しています…',generating:'AIキャラクターを作成しています…',ready:'完成しました！',failed:'生成できませんでした。スタッフにお声がけください'},
en:{title:'Just a moment—your cute new look is on its way!',label:'AI character progress',note:'The choices will appear automatically when ready.',steps:['Upload','Queue','Create','Ready'],uploading:'Uploading your photo…',queued:'Photo received. Getting ready…',generating:'Creating your AI character…',ready:'Ready! Meet your AI character',failed:'Generation could not be completed. Please ask our staff.'}
};
const WAIT_LINES={"zh": ["黑熊陪你，等一張專屬驚喜", "捕捉你的笑容，收藏這一刻", "轉個圈，遇見不一樣的自己", "揮揮手，和可愛的自己打聲招呼"], "jp": ["クマと一緒に、特別な一枚を待ちましょう", "あなたの笑顔を、思い出の一枚に", "くるっと回って、新しい自分に出会おう", "手を振って、かわいい自分にごあいさつ"], "en": ["A little bear, a little wait, a portrait just for you.", "Capturing your smile and this special moment.", "A little twirl. A whole new you.", "Wave hello to your cute new look!"]};
const BEAR_ASSETS={"original": "data:image/webp;base64,", "actions": "data:image/webp;base64,"};
const clamp=(n,min,max)=>Math.max(min,Math.min(max,Number(n)||0));
function createDisplayProgress(){return{current:0,target:0,phase:'uploading'}}
function targetFor(p,n){if(p==='ready'||p==='completed')return 100;if(Number.isFinite(Number(n)))return clamp(n,0,98);if(p==='generating')return 58;if(p==='queued'||p==='pending')return 28;return 8}
function mount(host,lang,shared){
 if(!host)throw new Error('Missing progress host');
 const locale=C[lang]?lang:'zh',c=C[locale],lines=WAIT_LINES[locale],d=shared||createDisplayProgress();
 host.innerHTML=`<section class="tourism-wait" data-phase="uploading" aria-live="polite">
<style>
.medical-actions-v30 .boba-character { transform-origin:50% 90%; }
.medical-actions-v30 .bear-source-original { background-image:var(--bear-sprite); }
.medical-actions-v30 .bear-source-actions { background-image:var(--bear-actions); }
.medical-actions-v30 .bear-pose { transition:none; }
.medical-actions-v30 .camera-flash { position:absolute; left:55%; top:35%; color:#fff; text-shadow:0 0 9px #fff8c8; font-size:clamp(20px,5vw,48px); line-height:1; opacity:0; pointer-events:none; }
.medical-actions-v30[data-action="camera"] .camera-flash { animation:bear-camera-flash 5s ease-out infinite; }
.medical-actions-v30[data-action="camera"] .boba-character { animation:bear-camera-bob 5s ease-in-out infinite; }
.medical-actions-v30[data-action="turn"] .boba-character { animation:bear-turn-bounce 2.5s ease-in-out infinite; }
.medical-actions-v30[data-action="wave"] .boba-character { animation:bear-hello 1.6s ease-in-out infinite; }
.medical-actions-caption { min-height:2.8em; line-height:1.4; display:flex; align-items:center; justify-content:center; text-wrap:balance; }
.tourism-wait[data-phase="failed"] .medical-actions-v30 *, .medical-actions-v30.is-paused * { animation-play-state:paused !important; }
@keyframes bear-camera-flash { 0%,28%,33%,68%,73%,100% { opacity:0; transform:scale(.3); } 30%,70% { opacity:1; transform:scale(1.1); } }
@keyframes bear-camera-bob { 0%,100% { transform:translateY(0); } 28%,68% { transform:translateY(-3px) rotate(-1deg); } 32%,72% { transform:translateY(1px) rotate(1deg); } }
@keyframes bear-turn-bounce { 0%,100% { transform:translateY(0); } 45% { transform:translateY(-6px); } }
@keyframes bear-hello { 0%,100% { transform:rotate(-2deg); } 50% { transform:rotate(2deg) translateY(-3px); } }
@media(prefers-reduced-motion:reduce) { .medical-actions-v30 * { animation:none !important; }.medical-actions-v30 .camera-flash { display:none; } }
</style>
<div class="tourism-kv-stage medical-animation medical-actions-v30" data-action="boba" aria-hidden="true">
<div class="boba-halo"></div><div class="boba-shadow"></div>
<div class="boba-character" style="--bear-sprite:url(${BEAR_ASSETS.original});--bear-actions:url(${BEAR_ASSETS.actions})">
<span class="bear-pose tourism-kv-accent bear-source-original is-visible"></span>
<span class="bear-pose tourism-kv-accent bear-source-actions"></span>
<span class="camera-flash">✦</span></div>
<span class="boba-spark boba-spark-one">✦</span><span class="boba-spark boba-spark-two">✦</span></div>
 <p class="tourism-wait-title medical-actions-caption" aria-live="off">${lines[0]}</p>
 <div class="tourism-progress-heading"><span class="tourism-progress-label">${c.label}</span><strong class="tourism-percent">0%</strong></div>
 <div class="tourism-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><div class="tourism-fill"></div></div>
 <ol class="tourism-milestones">${c.steps.map(x=>`<li>${x}</li>`).join('')}</ol>
 <p class="tourism-status">${c.uploading}</p><p class="tourism-progress-note">${c.note}</p></section>`;
 const root=host.querySelector('.tourism-wait'),pct=host.querySelector('.tourism-percent'),fill=host.querySelector('.tourism-fill'),track=host.querySelector('.tourism-track'),status=host.querySelector('.tourism-status'),marks=[...host.querySelectorAll('.tourism-milestones li')],stage=host.querySelector('.medical-actions-v30'),caption=host.querySelector('.tourism-wait-title'),originalPose=host.querySelector('.bear-source-original'),actionPose=host.querySelector('.bear-source-actions');
 let dead=false,scene=-1,elapsed=0,lastTime=Date.now(),lastPose='';
 const copyStatus=p=>p==='ready'||p==='completed'?c.ready:p==='failed'?c.failed:p==='generating'?c.generating:p==='queued'||p==='pending'?c.queued:c.uploading;
 function paint(){const n=Math.round(clamp(d.current,0,100));pct.textContent=n+'%';fill.style.width=n+'%';track.setAttribute('aria-valuenow',String(n));status.textContent=copyStatus(d.phase);root.dataset.phase=d.phase;const reached=n>=100?4:n>=48?3:n>=20?2:1;marks.forEach((x,i)=>x.classList.toggle('is-done',i<reached))}
 const progressTimer=setInterval(()=>{if(dead)return;if(!['ready','completed','failed'].includes(d.phase))d.target=Math.min(96,Math.max(d.target,d.current+.08));const gap=d.target-d.current;d.current=Math.abs(gap)<.04?d.target:d.current+Math.max(.04,gap*.075);paint()},80);
 const reducedMotion=()=>!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 const positions=['0% 0%','100% 0%','0% 100%','100% 100%'];
 function showPose(source,frame,mirror=false){
  const key=source+':'+frame+':'+mirror;if(key===lastPose)return;lastPose=key;
  const active=source==='original'?originalPose:actionPose;
  originalPose.classList.toggle('is-visible',active===originalPose);
  actionPose.classList.toggle('is-visible',active===actionPose);
  active.style.backgroundPosition=positions[frame];
  active.style.transform=mirror?'scaleX(-1)':'none';
 }
 function paintAnimation(){
  const next=Math.floor(elapsed/5000)%4,t=elapsed%5000;
  if(next!==scene){scene=next;stage.dataset.action=['boba','camera','turn','wave'][scene];caption.textContent=lines[scene];}
  if(scene===0)showPose('original',t<700?0:t<2400?1:t<3200?0:t<4500?1:0);
  else if(scene===1)showPose('actions',0);
  else if(scene===2){
   const turn=t%2500;
   if(turn<650||turn>=1650)showPose('actions',1);
   else{const frame=Math.floor((turn-650)/250);showPose('actions',[1,2,3,2][frame],frame===3);}
  }else showPose('original',3);
 }
 const animationTimer=setInterval(()=>{
  if(dead)return;const now=Date.now(),delta=Math.max(0,Math.min(250,now-lastTime));lastTime=now;
  const paused=document.hidden||d.phase==='failed'||reducedMotion();stage.classList.toggle('is-paused',paused);
  if(paused)return;elapsed=(elapsed+delta)%20000;paintAnimation();
 },100);
 function update(p={}){d.phase=p.phase||p.status||d.phase;d.target=targetFor(d.phase,p.percent);paint()}
 function reset(){d.current=0;d.target=0;d.phase='uploading';elapsed=0;scene=-1;lastTime=Date.now();lastPose='';paintAnimation();paint()}
 paintAnimation();paint();return{update,reset,dispose(){dead=true;clearInterval(progressTimer);clearInterval(animationTimer);host.innerHTML=''}}
}
function preload(url){return new Promise(resolve=>{if(!url)return resolve();const img=new Image(),done=()=>resolve();img.onload=done;img.onerror=done;img.src=url;setTimeout(done,10000)})}
function monitor(o){
 const base=String(o.apiBase||'').replace(/\/$/,''),id=encodeURIComponent(o.taskId),start=Date.now();let stopped=false,timer=null,errors=0,done=false;
 const emit=p=>{if(!stopped&&typeof o.onProgress==='function')o.onProgress(p)};
 async function poll(){if(stopped||done)return;try{const r=await fetch(`${base}/api/status/${id}`,{cache:'no-store'}),x=await r.json();if(!r.ok||x.success===false)throw new Error(x.error||'status error');errors=0;const elapsed=Date.now()-start;
  if(x.status==='failed'){emit({phase:'failed',percent:Math.min(96,55+elapsed/5000)});stopped=true;if(typeof o.onFailure==='function')o.onFailure(x);return}
  if(x.status==='completed'&&x.resultImageA&&x.resultImageB){done=true;emit({phase:'generating',percent:98});await Promise.all([preload(x.resultImageA),preload(x.resultImageB)]);if(stopped)return;emit({phase:'ready',percent:100});if(typeof o.onReady==='function')o.onReady(x);return}
  emit(x.status==='generating'?{phase:'generating',percent:Math.min(96,46+elapsed/3600)}:{phase:x.status||'queued',percent:Math.min(44,24+elapsed/7000)});
 }catch(e){errors++;emit({phase:'queued',percent:Math.min(44,22+(Date.now()-start)/8000)});if(errors>=20){stopped=true;if(typeof o.onFailure==='function')o.onFailure({error:e});return}}
 if(!stopped&&!done)timer=setTimeout(poll,1500)}
 emit({phase:'queued',percent:22});poll();return{stop(){stopped=true;if(timer)clearTimeout(timer)}}
}
window.TourismProgress={createDisplayProgress,mount,monitor};
})();



